import{Z as e,e as s,f as i,a0 as a}from"./chunks/framework.DmpHOl9T.js";const c=JSON.parse('{"title":"Option Sources","description":"","frontmatter":{},"headers":[],"relativePath":"fields/option-sources.md","filePath":"fields/option-sources.md","lastUpdated":1780994610000}'),n={name:"fields/option-sources.md"};function o(r,t,l,h,d,p){return s(),i("div",null,[...t[0]||(t[0]=[a(`<h1 id="option-sources" tabindex="-1">Option Sources <a class="header-anchor" href="#option-sources" aria-label="Permalink to &quot;Option Sources&quot;">​</a></h1><p>Use the <strong>Options</strong> setting on Dropdown, Radio and Checkboxes when the available choices should come from something other than a manually maintained options table.</p><p>Option sources are useful for long or changing lists — countries, CRM picklists, Mailchimp interest groups, HubSpot form properties — without copying hundreds of rows into the field or relying on Twig overrides on every render.</p><h2 id="choosing-an-option-type" tabindex="-1">Choosing an Option Type <a class="header-anchor" href="#choosing-an-option-type" aria-label="Permalink to &quot;Choosing an Option Type&quot;">​</a></h2><p>In the form builder, open the field’s <strong>Options</strong> setting and pick one of the available types:</p><table tabindex="0"><thead><tr><th>Option type</th><th>Use when</th></tr></thead><tbody><tr><td><strong>Static</strong></td><td>You define options manually in the options table, or import them once with <strong>Bulk add options</strong>.</td></tr><tr><td><strong>Predefined</strong></td><td>You want a built-in list such as countries, states, currencies or languages. Formie resolves the list at render time.</td></tr><tr><td><strong>Integration</strong></td><td>You want options from a connected integration’s cached data — for example Mailchimp interests or a CRM picklist.</td></tr><tr><td><strong>Template</strong></td><td>A developer supplies the option list in Twig when the form is rendered. Formie does not store or strictly validate that list.</td></tr></tbody></table><p><strong>Integration</strong> only appears when at least one enabled integration in your project supports option sources.</p><p>Predefined and Integration both resolve options at render time. The form builder still shows them as separate choices because the setup steps are different.</p><h2 id="static" tabindex="-1">Static <a class="header-anchor" href="#static" aria-label="Permalink to &quot;Static&quot;">​</a></h2><p>Use <strong>Static</strong> for short, fixed lists you want full control over in the form builder.</p><ul><li>Edit options directly in the options table.</li><li>Use <strong>Bulk add options</strong> to paste many rows at once, or start from a predefined list and copy rows into the static table.</li><li>Option <strong>availability</strong> (visible, hidden, disabled) is managed per row.</li><li>Submitted values are stored without a separate label snapshot.</li></ul><p>Static options use the field’s <code>options</code> table.</p><h2 id="predefined" tabindex="-1">Predefined <a class="header-anchor" href="#predefined" aria-label="Permalink to &quot;Predefined&quot;">​</a></h2><p>Use <strong>Predefined</strong> for common datasets Formie ships with, without maintaining hundreds of rows yourself.</p><ol><li>Set <strong>Options</strong> to <strong>Predefined</strong>.</li><li>Choose the <strong>List</strong> — for example countries, states/provinces, currencies or languages.</li><li>Choose which source fields to use for <strong>Option Label</strong> and <strong>Option Value</strong>.</li></ol><p>Formie resolves the list when the form is rendered. The <strong>Preview</strong> panel shows a sample of the resolved rows.</p><p>You can still use <strong>Bulk add options</strong> while the field is <strong>Static</strong> if you want to copy a predefined subset into the options table and then keep curating it manually.</p><h2 id="integration" tabindex="-1">Integration <a class="header-anchor" href="#integration" aria-label="Permalink to &quot;Integration&quot;">​</a></h2><p>Use <strong>Integration</strong> when options should follow data from a connected provider.</p><ol><li>Set <strong>Options</strong> to <strong>Integration</strong>.</li><li>Choose the <strong>Integration</strong> instance.</li><li>If the integration exposes more than one source, choose the <strong>Source</strong> — for example HubSpot <strong>Form Fields</strong> vs <strong>CRM Properties</strong>.</li><li>Complete any additional settings shown for that source — such as the HubSpot form, CRM object, or remote field.</li></ol><table tabindex="0"><thead><tr><th>Integration</th><th>What you can select</th></tr></thead><tbody><tr><td><strong>Mailchimp</strong></td><td>Interest groups and tags from a list</td></tr><tr><td><strong>HubSpot</strong></td><td>Form fields, or CRM properties on contacts, companies, deals and tickets</td></tr><tr><td><strong>Salesforce</strong></td><td>Picklist fields on contacts, leads, opportunities, accounts and cases</td></tr><tr><td><strong>Zoho</strong></td><td>Picklist fields on contacts, deals, leads, accounts and quotes</td></tr><tr><td><strong>Microsoft Dynamics 365</strong></td><td>Picklist fields on contacts, leads, opportunities, accounts and cases</td></tr></tbody></table><p>Before an integration source can return options, refresh the provider data in the form’s <strong>Integrations</strong> tab — for example field mapping for CRM objects, or HubSpot forms for form-field sources.</p><p>In the field settings <strong>Preview</strong> panel, use <strong>Refresh</strong> to:</p><ul><li><strong>Refresh Preview</strong> — re-resolve options from the current cached integration data.</li><li><strong>Refresh Integration Data</strong> — fetch fresh data from the provider, then reload the source configuration.</li></ul><h3 id="convert-to-static-options" tabindex="-1">Convert to Static Options <a class="header-anchor" href="#convert-to-static-options" aria-label="Permalink to &quot;Convert to Static Options&quot;">​</a></h3><p>When a <strong>Predefined</strong> or <strong>Integration</strong> source is configured, <strong>Convert to Static Options</strong> resolves the current remote list and copies the rows into the static options table. The field switches to <strong>Static</strong> and drops the provider link. Use this when you want to freeze a snapshot or stop depending on the remote source.</p><h2 id="template" tabindex="-1">Template <a class="header-anchor" href="#template" aria-label="Permalink to &quot;Template&quot;">​</a></h2><p>Use <strong>Template</strong> when the option list should be built in Twig for a specific page, user, entry or request — and you accept that Formie will not manage that list in the form builder.</p><p>When <strong>Template</strong> is selected, the options table and provider settings are hidden. The form builder shows a short note that options are supplied at render time.</p><h3 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h3><ol><li>Save the field with <strong>Options</strong> set to <strong>Template</strong>. You do not define rows in the form builder.</li><li>In your template, load the form and override the field’s <code>options</code> before rendering.</li><li>Formie renders whatever option array you supplied for that request.</li></ol><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> form </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> craft.formie.forms.handle(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;contactForm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).one() %}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> departments </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> craft.entries()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .section(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;departments&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .orderBy(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;title&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .all() %}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> form.setFieldSettings(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;department&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    options: departments</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">map(entry =&gt; {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        label: entry.title,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        value: entry.slug,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        default: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}) %}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ craft.formie.renderForm(form) }}</span></span></code></pre></div><p>You can also pass a plain array when the list is not element-driven:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> form.setFieldSettings(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;priority&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    options: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        { label: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Low&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, value: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;low&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, default: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        { label: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Normal&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, value: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;normal&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, default: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        { label: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;High&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, value: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;high&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, default: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}) %}</span></span></code></pre></div><p>For nested fields inside Group or Repeater fields, include the parent handle — for example <code>contactDetails.department</code>. See <a href="/templates/overriding-settings">Overriding Settings</a> for more field-override examples.</p><h3 id="caveats" tabindex="-1">Caveats <a class="header-anchor" href="#caveats" aria-label="Permalink to &quot;Caveats&quot;">​</a></h3><p><strong>No strict option validation.</strong> Formie does not apply an <code>in</code> range against a stored list for template fields. Submitted values are accepted as long as they pass the field’s other rules (required, format, and so on). Your template is responsible for supplying sensible choices.</p><p><strong>No builder preview.</strong> The form builder cannot know what your template will output, so there is no meaningful option preview while editing the field.</p><p><strong>Nothing is stored on the field.</strong> Template mode does not persist an option list in the field settings. If you forget to override <code>options</code> in Twig, the field may render with no choices.</p><p><strong>Cached pages need extra care.</strong> Template overrides run when Twig renders the form. On a statically cached page, the cached HTML keeps the options from the render that built the cache. Formie’s cached-form support refreshes request tokens, but it does not re-run Twig overrides or rebuild field markup on each page load. See <a href="/frontend/cached-forms">Cached Forms</a> and <a href="/templates/overriding-settings">Overriding Settings</a>.</p><p><strong>Reporting and integrations.</strong> Different page renders may expose different option sets to the same field handle. That can be intentional, but plan for it in exports, reporting and CRM mappings.</p><p><strong>Prefer Predefined or Integration when possible.</strong> If the list comes from a stable provider Formie already supports, use <strong>Predefined</strong> or <strong>Integration</strong> instead. You get builder preview, refresh controls, stricter validation and consistent behaviour on cached forms.</p><h3 id="when-template-mode-is-a-good-fit" tabindex="-1">When Template Mode Is a Good Fit <a class="header-anchor" href="#when-template-mode-is-a-good-fit" aria-label="Permalink to &quot;When Template Mode Is a Good Fit&quot;">​</a></h3><ul><li>Options depend on the current entry, category, site or logged-in user.</li><li>A developer controls the template and wants full flexibility per render.</li><li>The list is intentionally different on different templates that reuse the same form.</li></ul><h3 id="when-to-use-something-else" tabindex="-1">When to Use Something Else <a class="header-anchor" href="#when-to-use-something-else" aria-label="Permalink to &quot;When to Use Something Else&quot;">​</a></h3><ul><li>Authors should manage or preview the list in the form builder → <strong>Static</strong>, <strong>Predefined</strong> or <strong>Integration</strong>.</li><li>The list must be validated strictly against known values at submit time → <strong>Static</strong>, <strong>Predefined</strong> or <strong>Integration</strong>.</li><li>The form is often served from static cache without per-request Twig execution → avoid <strong>Template</strong>, or ensure the cache varies per context.</li></ul><h2 id="submitted-values" tabindex="-1">Submitted Values <a class="header-anchor" href="#submitted-values" aria-label="Permalink to &quot;Submitted Values&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option type</th><th>What is stored</th></tr></thead><tbody><tr><td><strong>Static</strong></td><td>The selected value only.</td></tr><tr><td><strong>Predefined</strong> / <strong>Integration</strong></td><td>The selected value and label.</td></tr><tr><td><strong>Template</strong></td><td>The selected value and label from the options you supplied at render time.</td></tr></tbody></table><p>Storing the label with the value keeps email notifications, exports and control panel previews accurate when the remote list changes later.</p><p>Keep option <strong>values</strong> stable once submissions, integrations or reports depend on them. Changing a value in the provider can invalidate older submissions during strict validation.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p><strong>Static</strong>, <strong>Predefined</strong> and <strong>Integration</strong> validate submitted values against the resolved option list at submit time.</p><p><strong>Template</strong> does not enforce an <code>in</code> range against a stored list. Use it only when a developer controls the render-time options deliberately.</p><h2 id="picking-entries-categories-users-or-tags" tabindex="-1">Picking Entries, Categories, Users or Tags <a class="header-anchor" href="#picking-entries-categories-users-or-tags" aria-label="Permalink to &quot;Picking Entries, Categories, Users or Tags&quot;">​</a></h2><p><strong>Predefined</strong> and <strong>Integration</strong> on Dropdown, Radio and Checkboxes cover built-in lists and integration data only.</p><p>When authors need users to pick Craft elements, use the dedicated field types instead:</p><ul><li><a href="/fields/entries">Entries</a></li><li><a href="/fields/categories">Categories</a></li><li><a href="/fields/users">Users</a></li><li><a href="/fields/tags">Tags</a></li></ul><p>Those fields use element queries and return element IDs, which fits relations, GraphQL and integration mapping better than treating elements as flat option rows.</p>`,58)])])}const u=e(n,[["render",o]]);export{c as __pageData,u as default};
